quests[60019] = { id = 60019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowlands 60 E" }
quests[60020] = { id = 60020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Opportunistic Strike", description = "I'm impressed you made it this far. But don't get too full of yourself.\n\nMost of the fodder you plowed your way through were amateurs at best. Only one combatant will leave this arena a champion.\n\nEach of the five... uh, three houses has fighters in the field. Most merely seek to test their own limits or earn a bit of favor. Only a few have a real chance at claiming victory.\n\nSeek out those challengers if you wish to claim true glory this day.", progress = "Are they finished?", completion = "Still walking on two legs? My hopes for you are rising.", objectives = "Slay 10 elite contenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60021] = { id = 60021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion the Cause", description = "Now you're starting to show potential! I'm guessing your name was well known on whatever mortal world you hail from.\n\nBut don't rest on your laurels. The harder you fight, the harder others will strive to strike you down. That's the Maldraxxi way!\n\nNothing wins the favor of the crowd like taking down a former champion. Two are in attendance today, attempting to recapture their past glories.\n\nSlaughter them!", progress = "Is it done?", completion = "Good, the crowd's on your side.\n\nNow there's just one last test.", objectives = "Slay Champion Rin'mar and Champion Gutrend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60023] = { id = 60023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowlands (60) E" }
