quests[60092] = { id = 60092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skoldus Hall", description = "<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.>\n\n<It beckons you to touch it.>", objectives = "Enter Skoldus Hall and defeat its warden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60096] = { id = 60096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King: To Northrend!", description = "The Lich King stirs in the north.\n\nAn undead army follows his command, marching across Northrend and spreading blight wherever they tread.\n\nWe need you to stop them, {name}.", objectives = "Take a ship to Northrend.\n\nYou can board the ship to Borean Tundra in Stormwind Harbor, or the ship to Howling Fjord in Wetlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60097] = { id = 60097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King: To Northrend!", description = "The Lich King stirs in the north.\n\nAn undead army follows his command, marching across Northrend and spreading blight wherever they tread.\n\nWe need you to stop them, {name}.", objectives = "Take a zeppelin to Northrend.\n\nYou can board the Howling Fjord zeppelin in Tirisfal Glades, or the Borean Tundra zeppelin in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60098] = { id = 60098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End is Now", completion = "It is time.", objectives = "Meet with Xandria near the central chamber of the House of Constructs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60099] = { id = 60099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fracture Chambers", description = "<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.>\n\n<It beckons you to touch it.>", objectives = "Enter the Fracture Chambers and defeat its warden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60100] = { id = 60100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soulforges", description = "<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.>\n\n<It beckons you to touch it.>", objectives = "Enter the Soulforges and defeat its warden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
