quests[60107] = { id = 60107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Winding Halls", description = "<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.>\n\n<It beckons you to touch it.>", objectives = "Enter the Winding Halls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60108] = { id = 60108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drust and Ashes", description = "The Drust encroach upon the Grove of Awakening, {name}!\n\nWe must fly in defense of Ardenweald!", completion = "Well done, huntsman.\n\nYou have saved Ardenweald from the Drust, and in so doing, protected countless other realms from their darkness.", objectives = "Defend the Grove of Awakening from the Drust and slay Gorak Zhar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60110] = { id = 60110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Had a Friend Like Me", description = "I feel like you could use a little help, Maw Walker. There is knowledge I have which could make you more useful to the Necrolords.\n\nSo just this once... I will teach you something and you won't even have to lose a limb.\n\nSoulbind with me and we'll see if you can learn anything.", completion = "Now you can try to live up to my example.", objectives = "Complete the soulbinding ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60111] = { id = 60111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging A Friendship", description = "When you first arrived I was uncertain of your potential. The Primus demands such perfection in his work... and you are far from perfect.\n\nI see now that you bring new knowledge and ideas to our house. Your actions make us stronger. The Primus would be proud of you and wish for us all to learn from you. \n\nI am ready now to know your ways.\n\nLet me soulbind with you now, so we can grow stronger together.", completion = "Our shared knowledge will benefit all of Maldraxxus.", objectives = "Complete the soulbinding ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60112] = { id = 60112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cut to the Bone", description = "I fear if our presence is known, so too is the presence of our comrades.\n\nWe must develop a contingency. With the foundry on such high alert, we cannot sneak about undetected.\n\nUnless, of course, you were to provide a distraction. Perhaps thinning their numbers would suffice.", completion = "He ought to be here... but he isn't.", objectives = "Eliminate 5 Ossein Workers and 10 Violent Animates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60113] = { id = 60113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Urgent Request", description = "Champion,\n\nA matter of great urgency has arisen--one that requires your immediate attention.\n\nDue to the sensitive nature of recent events, I must withhold further details until we meet.\n\nWe have much to discuss. King Greymane and I await your arrival at Lion's Rest.", completion = "I knew you would not hesitate to answer the call, {name}.\n\nI will be brief.", objectives = "Report to Genn Greymane at Lion's Rest in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60114] = { id = 60114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aerial Advantage", description = "Gharmal's rocs dominate the skies above, striking at our forces as we advance. We cannot move the necropolis into position until they are cleared out!\n\nI would slaughter them myself, but the cowards remain out of reach, and I am not constructed for flight.\n\nYou, however, seem slight enough of build. Take my riding hook and latch onto a roc. \n\nOnce you are atop of one, beat it to a pulp. Worry about the landing later.", progress = "Annihilate them!", completion = "I could hear their cries from here. Nice work!", objectives = "Grapple 6 Battlesewn Rocs out of the sky.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60115] = { id = 60115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Urgent Request", description = "Champion,\n\nA matter of great urgency has arisen--one that requires your immediate attention.\n\nDue to the sensitive nature of recent events, I must withhold further details until we can speak in person.\n\nThere is much to discuss. Regent Lord Lor'themar Theron awaits your arrival in Orgrimmar.", completion = "It has been some time since I last stood here, staring into the distance...\n\nHow could this have happened?\n\nI'm afraid I have difficult news to share with you, {name}.", objectives = "Report to Lor'themar Theron atop Grommash Hold in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60116] = { id = 60116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cause for Distraction", description = "The very heart of the Alliance is under attack.\n\nThe undead Scourge is swarming in numbers not seen since the return of Arthas Menethil. Amidst the chaos, something... terrible has happened.\n\nWhat I am about to share with you has not yet been revealed to our allies. They will be told in due time, but I needed to speak to you directly before word gets out.\n\nAllow me to explain.", progress = "There is much to discuss.", completion = "We must find a way to rescue Anduin and the others. But in this moment, the safety of our citizens and our allies is our highest priority.\n\nAs such, I have reached out to those experienced in dealing with threats of this nature.", objectives = "Speak with Genn Greymane at Lion's Rest in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60117] = { id = 60117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Crusade", description = "The Scourge's unbound hunger has been unleashed. It's only a matter of time before those monsters swarm our streets.\n\nWe need expertise in dealing with this menace. The death knights of the Ebon Blade have stepped forward to aid us, but even they can't do this alone.\n\nThe Argent Crusade has answered the call. I need you to work with them to keep our people safe, {name}.\n\nI have sent word of your arrival to their commander. He awaits you at their camp just inside the city gates.", completion = "Ah, I was told to expect the arrival of a seasoned {class}.\n\nLet's get to work.", objectives = "Speak with Commander Gregor in the Trade District of Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60120] = { id = 60120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade: To Outland!", description = "The Burning Legion - an uncountably vast army of demons - has assaulted Outland, the tattered homeworld of the draenei. Adventurers of the Alliance are needed to protect what remains of Outland from utter annihilation at the hands of this demonic invasion.\n\nTravel to the Blasted Lands, and pass through the Dark Portal.", objectives = "Go through the Dark Portal in Blasted Lands.\n\nThe Honor Hold Mage in the Mage District can help you get there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60123] = { id = 60123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade: To Outland!", description = "The Burning Legion - an uncountably vast army of demons - has assaulted Outland, the tattered homeworld of the orcs. Adventurers of the Horde are needed to protect what remains of Outland from utter annihilation at the hands of this demonic invasion.\n\nTravel to the Blasted Lands, and pass through the Dark Portal.", objectives = "Go through the Dark Portal in Blasted Lands.\n\nThe Thrallmar Mage in the Orgrimmar Portal Room can help you get there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60125] = { id = 60125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mists of Pandaria: To Pandaria!", description = "Please come to Stormwind Keep immediately for a briefing with King Varian Wrynn.\n\nWe have received word of a conflict in the seas to the south, and we need the help of an experienced {class} to assist in the investigation.", completion = "Greetings, {name}.", objectives = "Report to Rell Nightwind in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60126] = { id = 60126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mists of Pandaria: To Pandaria!", description = "You are hereby ordered to present yourself at Grommash Hold immediately.\n\nWe have received word of a new, resource-rich continent in the south, and we intend to send you and a small contingent of soldiers to claim it for the Horde.", completion = "Lok'tar, {name}.", objectives = "Report to Grommash Hold in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60127] = { id = 60127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Stone Fiend", description = "You or I could wield these sinstones directly, but I much prefer to use stone fiends for such tasks.\n\nExceptional results, no personal risk.\n\nUnfortunately, my stone fiend did not return from its last errand.\n\nSpeak with Cryptkeeper Kassir in the archives above. He is loyal to the Accuser and will loan us his stone fiend.", completion = "<Cryptkeeper Kassir grins.>\n\nSo you finally listened to the Accuser, eh?\n\nBetter late than never.", objectives = "Speak with Cryptkeeper Kassir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60128] = { id = 60128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready to Serve", description = "Do not mind Temel. His zeal for heralding sins is powerful, but he is still a stone fiend. He will obey.\n\nGive Archivist Fane my regards.", completion = "Temel has told me quite the tale of your previous adventures together, Maw Walker.", objectives = "Return to Archivist Fane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60129] = { id = 60129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranger in an Even Stranger Land", description = "<You arrive alone at the precipice of a strange city, knowing the leaders of Azeroth remain trapped in the Maw.\n\nWherever you are, it is clearly very, very far from home.\n\nIt appears your arrival has been noticed.>", progress = "Try to communicate with the guards and enter the city.", completion = "Could it be? An actual mortal being in the Eternal City? The Purpose be served!", objectives = "Find your way inside Oribos to learn what is happening.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60132] = { id = 60132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Constellan Writs and Stygia", description = "There is much to discover within the Maw, and much of it can be turned to future profit.\n\nInformation is an investment.\n\nThere are many objects that I find interesting in this place, and I am happy to barter with you should you find any.\n\nFind one and we shall open negotiations." }
quests[60136] = { id = 60136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Torghast", description = "The bond to your covenant is growing stronger, {name}. Good. The power lies within you to venture into Torghast and rescue our allies.\n\nYou saw Baine Bloodhoof while assisting the broker in the Maw. Perhaps this Ve'nari knows a way to breach the Jailer's tower and find the chieftain.\n\nWhen I peered into Torghast once before, you stood at my side. I believe that connection will allow me to see through your eyes as you navigate its torments.\n\nSeek out Ve'nari and request her aid, Maw Walker.", progress = "Do whatever you can, Maw Walker. We are depending on you.", completion = "Well, Maw Walker, what are you waiting for?", objectives = "Find a way into Torghast, Tower of the Damned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60137] = { id = 60137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fracture Chambers", description = "The longer you stay within Torghast, the more difficult it becomes for me to hold our tether.\n\nBut I will not let go of our bond.\n\nI sense the Jailer's forces, but I also feel another energy: Maldraxxi forces. Strange.\n\nBeyond that, the faint echoes of another living soul. Let us hope it is one of our allies, and not some foul trick.\n\nKeep pressing onward.", objectives = "Enter the Fracture Chambers within Torghast and defeat its warden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60138] = { id = 60138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlocking the Gates" }
quests[60139] = { id = 60139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torment Chamber: Jaina", progress = "You must find Jaina Proudmoore in Torghast.", completion = "Two of Azeroth's architects of peace have been recovered.\n\nTwo remain captive.", objectives = "Rescue Jaina Proudmoore from Torghast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60140] = { id = 60140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mort'regar", description = "I have heard whispers of Mort'regar.\n\nA strange, shifting place between blocks of cells, filled with the shades of souls so tormented that they have forgotten who they once were.\n\nSuch a place could turn even the most stalwart heart to dust.", objectives = "Enter Mort'regar within Torghast and save Thrall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60141] = { id = 60141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coldheart Interstitia", description = "Torghast is a place of torments of both body and mind. Its very nature makes you doubt what is real.\n\n<Jaina falters a moment, then recovers her composure.>\n\nI caught fleeting glimpses of winged Mawsworn carrying Anduin and Thrall deeper into the tower. Taking them into the cold heart of vast cavernous recesses where light and hope seem like distant memories.\n\nDo whatever you must to pull them out of that tower. The Jailer's forces will do everything in their power to stop you.", objectives = "Enter Coldheart Interstitia within Torghast and slay its warden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60145] = { id = 60145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Third Talon Vartox", description = "This \"win the spirit of the people\" operation is noble and good. \n\nHowever, we must set our sights on cutting down our foe's tools. Third Talon Vartox, the leader of this incursion, also serves as the top stoneborn at the Tithelord's estate.\n\nIf we strike her down here, the Tithelord will be left exposed for our attack.", progress = "Is Vartox dealt with?", completion = "Excellent. Now he is left without his key defense.", objectives = "Kill Third Talon Vartox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60146] = { id = 60146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torment Chamber: Thrall", description = "Using the totem you recovered, I will alter the Attuned Shard to guide you to Thrall's location.\n\n<Bolvar hands you the crystalline object.>\n\nTake care. You know the torments Baine and Lady Proudmoore endured in that accursed place. Thrall's confinement will be no less harrowing.\n\nBeware. The deeper you journey into the Tower of the Damned, the closer you get to the Jailer himself.\n\nFree Thrall, {name}... before all hope is lost.", progress = "All our allies must be saved, {name}.", completion = "You have braved torments beyond most mortals' understanding, {name}.\n\nWell done indeed.", objectives = "Rescue Thrall from Torghast, Tower of the Damned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60147] = { id = 60147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mirror Attunement: The Eternal Terrace", description = "Work has been completed on a mirror that will allow travel between Sinfall and The Eternal Terrace. However, it has yet to be attuned.\n\nThe attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.", completion = "Well done! The mirrors have been attuned and can be used at your leisure.", objectives = "Enter the mirror in The Eternal Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60148] = { id = 60148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Place for the Living", description = "A living mortal ... incredible!\n\nForgive my astonishment. I am Kah-Delen, an overseer of the Arbiter's attendants here in the Eternal City of Oribos.\n\nYou stand within the heart of the Shadowlands. While we are accustomed to receiving souls from all manner of worlds within the mortal realm, never before has one arrived that is quite so ... corporeal.\n\nAnswer honestly, mortal. Did you truly escape the Maw?", progress = "So where did you come from stranger?", completion = "Finally, the Purpose may be guiding us again.", objectives = "The Overseers want to know more about how you escaped the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60149] = { id = 60149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audience with the Arbiter", description = "I am Tal-Inara, Honored Voice of the Arbiter. I speak for she who is ever silent.\n\nThe Arbiter watches over Oribos. She blesses us with her wisdom. Every mortal soul that enters the Shadowlands passes before her for judgment.\n\nIn the merest fraction of a moment, she sees every glory, every folly, every joy, every regret. With this knowledge, she chooses an ideal afterlife for that soul.\n\nAt least, she did. Not long ago, catastrophe struck, and ...\n\nCome. Some things are better seen than explained.", progress = "The Purpose guides us always.", completion = "We may find a shared cause in the Purpose. It has sent you to us.", objectives = "The Voice of the Arbiter wishes you to join them in the Arbiter's chamber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60150] = { id = 60150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tether to Home", description = "It is disappointing that you were unable to stir the Arbiter, but we must not give up hope.\n\nYour continued presence in the Shadowlands may help our cause. Perhaps your efforts would benefit from creating a tether to the mortal plane.\n\nThe map table in this chamber was put in place long ago by the First Ones, the wise architects of all you see.\n\nIf you have a memento from your homeworld, place it there. The table's magic can establish a connection.", completion = "{name}! I am relieved you survived that realm of darkness.\n\nI am eager to hear the tale.", objectives = "Affix the Helm of Domination fragment to the console.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60151] = { id = 60151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Doorway Through the Veil", description = "The Helm fragment connected us while you were in the Maw. As if through a darkened pane of glass, I saw glimpses of what you endured. The terrors you faced.\n\nAt least the heroes of Azeroth yet live. They must be saved.\n\nBy affixing the Helm here, you gave us a tether to Azeroth that served to bring a few of us across the veil. But you, and other heroes who join us, require a stronger connection.\n\nOur acolytes can open portals back. No doubt these attendants will be particular about their placement.", progress = "Have you helped the acolytes open the portals yet?", completion = "Your path and the Purpose are now entwining.", objectives = "Establish portals back to Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60152] = { id = 60152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eternal City", description = "You should become familiar with the Eternal City and how best to navigate it.\n\nWe, the attendants, serve Oribos as its caretakers. \n\nEverything you see here is done in service to the Purpose. In this time of chaos and drought, we must adapt our perspective. It seems we are to serve the Purpose in a new way.\n\nYou mortals are not the only visitors here. Others have come as well.\n\nLike you, the brokers are not of Oribos. They are congenial and willing to aid you. Usually for a price.", progress = "Have you concluded your tour yet?", completion = "We hope you are comfortable here, {name}.\n\nConsider these ancient facilities to be at your disposal.", objectives = "Tour the Eternal City of Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60153] = { id = 60153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Unknown", description = "Come to pay old Marasmius a visit? I have a special task for you.\n\nOne of my shoots has found a strange place, a place even I've never seen before.\n\nI'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for!\n\nWhat do you say, {name}? Up for an adventure?", progress = "Keep your guard up. It could lead anywhere!", completion = "It's a good thing you were there. The gorm have been very hungry lately, and I do not appreciate being nibbled on. Never been my thing!", objectives = "Investigate the unknown area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60154] = { id = 60154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Understanding the Shadowlands", description = "As I sat upon the Frozen Throne all those years, {name}, I could peer into the Shadowlands. Brief glimpses, clouded and uncertain. Sights both wondrous and terrible.\n\nWe must work together to make sense of what has happened. To prevent the Maw from consuming all of reality.\n\nWhatever Sylvanas and the Jailer want, we must stop them. But we cannot do so alone.\n\nPerhaps Tal-Inara can put us on the path to find answers.", progress = "Let us align your path to the Purpose.", completion = "Your path and that of the Purpose are becoming one.", objectives = "Speak to Tal-Inara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60155] = { id = 60155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Open the Way" }
quests[60156] = { id = 60156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path to Bastion", description = "Within the Arbiter's Chamber are gateways to the infinite realms of the Shadowlands. As each soul was judged, a gateway would be opened to the appropriate afterlife. \n\nBut since the... incident, all gateways have remained closed. Dormant.\n\nWe dare not use the Arbiter's sacred chamber for so mundane a purpose as travel. But here in the upper ring of the city, gateways can be configured for your needs.\n\nBefore us stands the means to activate a gateway. Together we can channel the anima to power it.", progress = "Your destiny and the Purpose are being drawn together.", completion = "Purpose be praised! Your path becomes clearer.", objectives = "Open the gateway to Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60157] = { id = 60157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Answers from the Ascended" }
quests[60158] = { id = 60158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rule 7: Betrayal is Inevitable", description = "Our arrangement has been quite lucrative. Reliable associates like yourself can be so hard to find.\n\nI believe I can entrust you with a task I would usually perform on my own.\n\nWhile working with the tracking runes you retrieved for me earlier, I detected a device of broker origin nearby. It must have been brought into the Maw by the captured expedition.\n\nPlease examine it and prepare it for transport back to the refuge. I will join you shortly.\n\nThis could be a valuable discovery.", progress = "Have you found the device?", completion = "It seems our partnership has become rather permanent. Cartel Ve will not rest until we are both eliminated.\n\nI suppose now would be the time to share one of my most important rules with you.", objectives = "Recover the broker device outside of Perdition Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60159] = { id = 60159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mirror Attunement: Halls of Atonement", description = "Work has been completed on a mirror that will allow travel between Sinfall and the Halls of Atonement. However, it has yet to be attuned.\n\nThe attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.", completion = "Well done! The mirrors have been attuned and can be used at your leisure.", objectives = "Enter the mirror in the Halls of Atonement.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60160] = { id = 60160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mirror Attunement: The Banewood", description = "Work has been completed on a mirror that will allow travel between Sinfall and The Banewood. However, it has yet to be attuned.\n\nThe attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.", completion = "Well done! The mirrors have been attuned and can be used at your leisure.", objectives = "Enter the mirror in The Banewood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60162] = { id = 60162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of Taming", description = "Quite the surprise to find this beast so hale and hearty. It seems to have taken a liking to you.\n\nIf you're ever going to be as great as one of the Dawntrackers, you must learn how to handle multiple pets.\n\nAllow me to show you how.", progress = "Be sure to dismiss your pet before we get started. Oh, and if it's injured, use Revive Pet to bring it back.", completion = "I don't believe there is anything left to teach you, {name}. \n\nNow you must go forth and find more beasts to tame and call your own.\n\nIf you ever need to store or retrieve your pets, speak with me or any other stable masters you encounter in your travels.", objectives = "Learn how to dismiss, tame, and stable pets from Mithran Dawntracker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60164] = { id = 60164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mirror Attunement: Dominance Keep", description = "Work has been completed on a mirror that will allow travel between Sinfall and Dominance Keep. However, it has yet to be attuned.\n\nThe attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.", completion = "Well done! The mirrors have been attuned and can be used at your leisure.", objectives = "Enter the mirror in Dominance Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60165] = { id = 60165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mirror Attunement: Feeders' Thicket", description = "Work has been completed on a mirror that will allow travel between Sinfall and Feeders' Thicket. However, it has yet to be attuned.\n\nThe attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.", completion = "Well done! The mirrors have been attuned and can be used at your leisure.", objectives = "Enter the mirror in Feeders' Thicket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60168] = { id = 60168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of Taming", description = "I'm quite surprised to find this beast still alive and kicking. It appears to like you.\n\nBefore we finish, you had better learn how to wrangle multiple pets.\n\nI'll give you one last lesson.", progress = "Make sure to dismiss your pet before we get started. Oh, and if it's injured, use Revive Pet to bring it back.", completion = "Excellent work, {name}. There's nothing left for me to teach you.\n\nGather as many wild beasts as you'd like. Just make sure not to lose focus on the ogres who are trying to kill us.", objectives = "Learn how to dismiss, tame, and stable pets from Austin Huxworth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60169] = { id = 60169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Area", description = "The Scourge's attack was as sudden as it was unexpected. Truth be told, they caught us unawares.\n\nThrough swift action, we were able to rally our defenses... though not before the tournament grounds were overrun.\n\nWe must secure the area before we can mount a counteroffensive.\n\nVanquish these monsters in the name of the Light!", completion = "It appears we are making headway.", objectives = "Remove 12 Scourge from the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60172] = { id = 60172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Quest is Temporary", description = "Dropping out of the sky is a key part of this playtest, so enjoy the ride.", objectives = "Speak with Draedan to enter the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60174] = { id = 60174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Divine's Shield", description = "This island has foul necromancy here in addition to the shadow magic. The Light can only just reach this place.\n\nCall upon its Divine Shield to step through the barrier before us unharmed and destroy this vile altar.\n\nShow the darkness on this island that you are protected by the Light's embrace.", progress = "Do you require aid? Use Divine Shield to safely cross pass the necrotic barrier.", completion = "You have done well, {name}. Dispel this foul magic wherever you encounter it.\n\nMy task has been fulfilled. The Light calls to me. \n\nGood luck, and remember that the Light's warmth will always embrace you.", objectives = "Cross the necrotic barrier with Divine Shield and destroy the Necrotic Altar. You can speak with Daelya Twilightbane if you need to use Divine Shield again.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60175] = { id = 60175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste of Tirna Noch", description = "I'm a simple mushroom with simple pleasures, {name}. And what's simpler than a nice, hearty meal?\n\nDon't look so surprised. I need to eat just like anyone else! How else do you think I grew so big? Nice, tasty compost, that's how!\n\nBack in my day, I had the pick of Ardenweald for where to feed. Now, not so much.\n\nI've had a hankering for some of the loam that used to be around Tirna Noch. I haven't had shoots out there in a long time. Could you bring me some?", progress = "Tirna Noch is a beautiful tree located east of Hibernal Hollow. You can't miss it.", completion = "Mmmm, it smells just like how I remember it! Maybe a little stale, but you won't hear me complaining about a job well done!", objectives = "Collect 6 Leafy Loam in Tirna Noch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60176] = { id = 60176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Out Your Tithe", description = "Unfortunately the Lord Chamberlain's gift isn't sufficient to cover the entire tithe we're expected to provide the Tithelord, but it will make a good start.\n\nThe loss of the tithe convoy is a terrible blow to our village. Our little community is already suffering greatly from the drought and the need to meet the Tithelord's demands. Still we must all do our part.\n\nWe have little time to accomplish this task. Can you help? Get the tithe from villagers and scour the area for every forgotten drop.", completion = "I was not sure this task was possible. Very impressive work.", objectives = "Collect anima from the village for the tithe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60177] = { id = 60177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reason for the Treason", description = "If you ask me, the attack on our convoy is suspicious. I told Mistress Mihaela that there must be a traitor in the village, but she isn't concerned. It's understandable. She's got to worry about gathering a new tithe.\n\nI've taken it upon myself to figure this out and I could use your help. I'm making discreet inquiries but I can't be seen speaking with the help. That's where you come in. You can be my assistant sleuth.", progress = "Have you identified the traitor yet?", completion = "Well, isn't that interesting information you've dug up.", objectives = "Speak with the \"help\" in the village to find clues leading to the identity of the traitor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60178] = { id = 60178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Then There Were None", description = "Ilka and Samu argued, you say? And you found a coded message indicating that the tithe was going to be sent out soon. Those are helpful clues that will allow me to put the puzzle together. \n\nIt's clear to me now who betrayed the village and what we need to do about it! You deliver invitations to a meeting to our suspects and I'll prepare to reveal the traitor.", progress = "The Master knows what's best for us. We must do our part.", completion = "Nice that it all worked out in the end. Thanks for the unintentional help.", objectives = "Gather the suspects and meet Lajos in the large crypt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60179] = { id = 60179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memory of Honor", description = "<A tablet sits embedded in the ground near a broken armor display.\n\nThe runes on the epitaph conjure images of an ancient warrior in your mind. Clearly Maldraxxus honors the history of those who claimed great victories here.\n\nSimilar memorials seem to be spread throughout the trench. Perhaps they can offer more insight into the denizens of this realm.>", progress = "Yes?", completion = "Many strive for greatness in Maldraxxus. Few truly achieve infamy.\n\nLet us see if our names will one day be remembered.", objectives = "Read 3 Faded Epitaphs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60180] = { id = 60180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Paragon's Reflection", description = "<The Vault-Keeper examines you.>\n\nYou appear to carry a signature unique to one of the Paragons. If you know which Paragon, simply peer into their Soul Mirror to examine the memory of your choice.\n\nIf you require anything else, you need only speak.", progress = "Did you find the memory you seek?", completion = "I hope your experience was satisfactory.", objectives = "Reveal the final memory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60181] = { id = 60181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trench Warfare", description = "These would-be recruits seek a way to prove themselves. Let us give them the chance.\n\nThe specter known as Malifis has grown in strength by consuming our anima reserves. In this time of drought, we cannot afford to lose any of our most precious resource. \n\nThis threat needs to be dealt with immediately.\n\nUse this horn to signal the scavengers we've recruited. Let us see how well they fight under our banner!", progress = "Take care, our quarry is formidable.", completion = "A threat removed for the House of the Chosen, and new recruits that show potential.\n\nGood work.", objectives = "Use the Baron's Warhorn to defeat Malifis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60182] = { id = 60182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feasting Soul Eater" }
quests[60183] = { id = 60183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "After Them!", description = "We must move quickly! That anima will be key in fueling these citizens for the fight ahead.\n\nDeathfang is ready to ride.", completion = "An excellent display of the strength of Sinfall, {name}. \n\nLet us continue, shall we?", objectives = "Board Deathfang and ride with Baroness Draka to stop the carriage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60184] = { id = 60184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dude, Where's My Necropolis?", description = "Maintaining the portal between our sanctum and the Zerekriss is a difficult task. With enough resources, we could make it permanent and become the unstoppable force my baroness wishes us to be.\n\nShe has asked much of you, as have I. But this work will make your name a legend among the Maldraxxi, as my baroness's has become.\n\nHelp to empower us, and you will be empowered in turn.", completion = "You do not cease to impress.", objectives = "Upgrade your Sanctum's portal system to Rank 2.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60185] = { id = 60185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - BFA - Ny'alotha Raid Finder - 1st" }
quests[60188] = { id = 60188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Beyond!", description = "Ah, you're just in time. I've made quite the discovery.\n\nI've managed to make a connection even further out than I ever have before.\n\nHow did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for!\n\nUp for an even more exciting adventure?", progress = "I feel a breeze on the other side. I guess that means it's not underground.", completion = "That was real nice of you. Not too many people take care of us old folks around here.\n\nShe even gave you silk! How nice. Here, why don't you take it? I certainly don't need it.", objectives = "Investigate the unknown area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60189] = { id = 60189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Strike Now", description = "The time has come. The Wild Hunt has driven the Drust back to their stronghold at the edge of Ardenweald.\n\nTheir scouts report that Gorak Zhar herself is among them. This may be our only opportunity to fully purge the minions of Thros from this realm.\n\nLord Herne awaits your arrival at the battlefront. Go with haste, {name}.", completion = "Good. You are here.\n\nWe are now ready to end the Drust's invasion once and for all.", objectives = "Meet Lord Herne outside of Darkreach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60190] = { id = 60190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Darkreach", description = "The Drust have inflicted enormous loss on this forest and its denizens, {name}. It is time we put an end to their atrocities.\n\nWe will drive the Drust from their enclave and close their gateway into Ardenweald. With you as our vanguard, victory is assured.\n\nI will make my way into the heart of their camp. Find me once you have routed their forces.", completion = "Well fought. The Wild Hunt will deal with the rest as necessary. There is one more foe for us to vanquish.\n\nAre you prepared?", objectives = "Assault the Drust forces within Darkreach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60191] = { id = 60191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ingra Drif", description = "Ingra Drif, the Drust captain, has been spotted inside Darkreach. This is our chance to destroy him for good.\n\nI know him and his cruelty all too well, {name}. Whatever you do to him, it's better than what he deserves.", completion = "Good. The Drust have been dealt a significant blow.\n\nThe spirits of those lost to Ingra Drif's treachery can at last be at peace.", objectives = "Slay Ingra Drif.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60192] = { id = 60192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Their Last Line of Defense", description = "Those sneaky Drust are protecting Gorak Zhar with their evil magic!\n\nI can sense several foul runes that are scattered across Darkreach. If you destroy them, we can easily shatter the barrier around that nasty Gorak Zhar.\n\nHurry! I will meet you inside the enemy camp.", completion = "Ha! There's nothing left to protect her now. Let's finish this!", objectives = "Destroy Gorak Zhar's shielding runes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60193] = { id = 60193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unmasked", description = "Thanks to your efforts, the shield that protects our prey has been made brittle as a dried leaf.\n\nOur hunt is all but complete. \n\nCome, let us put an end to the vile Gorak Zhar.", completion = "Oh, Ara'lon... even after all he endured, he found a way to smile again... only to...\n\n<Lady Moonberry wipes her eyes.>\n\nThere will be time for tears later. We still need to stop the Drust. For Ara'lon... and the forest he fought to protect.", objectives = "Slay Gorak Zhar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60194] = { id = 60194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of the Hunt", description = "I fear Lord Herne will have further need of our aid before this night is over.\n\nCome, I'll put some wings on you. We'll have to fly if we want to keep up with him.", completion = "Damn the Drust! This was all a diversion!", objectives = "Speak to Lord Herne in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60195] = { id = 60195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Build One More", description = "All these souls deserve a new construct, and when rebuilt any of them will make a valuable addition to our forces.\n\nWe must start somewhere. \n\nYou should be able to find Malleable Flesh through out the Shadowlands. A few of the other parts may be harder to locate.\n\nCollect parts and use the Abominable Stitching Table to build another construct.", progress = "Remember, you can find parts from almost anything in Maldraxxus.", completion = "So many powerful souls, this new additional shall bolster our forces greatly!", objectives = "Build one new construct.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60211] = { id = 60211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spore Losers" }
quests[60215] = { id = 60215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timely Gate Crashers", description = "Did you see that giant mechanical monstrosity just walking around in the dunes outside? How about the icky shadowy Sha of Anger? Or that big frost giant in the north? Yeah, they aren't native to this area. \n\nThey tell me the timeways are screwy around this time of year. They have asked me to organize a clean-up crew.\n\nWould you be up to the challenge? If you like this challenge, I have another for you as well.", progress = "How's it going?", completion = "Thanks for taking out Doomwalker, let's hope that doesn't happen again! It will though!", objectives = "Defeat Doomwalker, Sha of Anger, and Archavon the Stone Watcher in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60217] = { id = 60217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Archon's Answer", description = "Your cleansing is complete, and you are whole.\n\nOur plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene's attention once more. \n\nNow is our opportunity to request an audience with the Archon.\n\nStand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.", completion = "You are worthy of Bastion's grace, {name}. May it serve you well.", objectives = "Speak to Kalisthene.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60218] = { id = 60218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Archon's Answer", description = "Your cleansing is complete, and you are whole.\n\nOur plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene's attention once more. \n\nNow is our opportunity to request an audience with the Archon.\n\nStand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.", completion = "You are worthy of Bastion's grace, {name}. May it serve you well.", objectives = "Speak to Kalisthene.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
