quests[60229] = { id = 60229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Archon's Answer", description = "Your cleansing is complete, and you are whole.\n\nOur plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene's attention once more. \n\nNow is our opportunity to request an audience with the Archon.\n\nStand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.", completion = "You are worthy of Bastion's grace, {name}. May it serve you well.", objectives = "Speak to Kalisthene.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60230] = { id = 60230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More the Merrier", description = "News of our work here has spread, new souls have arrived seeking to join us!\n\nTake their requests for new construct bodies. We'll see if we can build them new constructs too!", completion = "So many souls, we have much work to do!", objectives = "Take the construct requests from the souls present.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60231] = { id = 60231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "State of Decay" }
quests[60236] = { id = 60236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RSVP: Cryptkeeper Kassir", description = "I would be most honored to attend Prince Renathal's Ember Court.\n\nI prefer to wear my official signet ring for such prestigious occasions. It was given to me by the Accuser herself when I was first charged with my duties.\n\nHowever, the Lord Chamberlain's goons have stolen it once more.\n\nThey hide their ill-gotten gains inside of these crypts... But I have no idea which one houses my ring.\n\nIt may take some time to find Atonement Crypt Keys, but any venthyr here in the halls could have one.", progress = "Desired objects tend to be in the last place we look, do they not? Perhaps we shall be fortunate this time.", completion = "My most gracious gratitudes to you, Maw Walker!\n\n<Cryptkeeper puts the ring into his pocket and pats it comfortably.>\n\nNow I may attend the Ember Court in my finest appearance.\n\nI do hope the Accuser will be performing rituals there...", objectives = "Collect Atonement Crypt Keys from venthyr around the Halls of Atonement and open Atonement Crypts until you find the Lost Cryptkeeper's Ring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60238] = { id = 60238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gently Shaken Gift", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special {race} {class}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60239] = { id = 60239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift", objectives = "A small tag on this present reads:\n\nHappy holidays, {name}!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60242] = { id = 60242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trading Favors: Necrotic Wake", description = "We of the brokers place value on things that may seem strange to an outsider like yourself. Objects that are unusual or one-of-a-kind are things we may find more valuable than others.\n\nSo let us make a deal, hm? Should you find yourself in possession of one such object, I will offer a trade for something you may find more valuable.\n\nI hear that the forces of Maldraxxus have made an attack on Bastion. Such things rarely happen without objects of power in tow, no?", progress = "Have you found any objects of interest?", completion = "Ah, quite a find, we rarely get a glimpse into the mechanisms by which the House of Rituals enact their dark designs. I am eager to delve into this tome, purely in the interests of knowledge of course.\n\nYou may choose from some of our procured items as a reward.", objectives = "Obtain Nalthor's Phylactery Instructions from Nalthor the Rimebinder in the Necrotic Wake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60243] = { id = 60243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trading Favors: Sanguine Depths", description = "The generals of Revendreth are outfitted with only the finest arms and armor, procured by Sire Denathrius in his unquenchable appetite for power. In terms of profitable trades and exchanges, he has been a shrewd partner in trade to us.\n\nIt would please me greatly to see the return of some relics that were traded in a way that benefited him far more than us. There are few things more insulting to my kind.", progress = "What have you brought before me?", completion = "Yes, yes this is exactly what I was speaking about. The foolish generals of Revendreth would use this medallion to orient themselves during travel in unknown areas, but their ambitions were small.\n\nFor my people, who have traveled beyond the known lands, such a thing is invaluable when attempting to chart a way to return.\n\nWe will make great use of this, it is good to see it returned. Here, a prize for you.", objectives = "Obtain a Medallion of Orientation from General Kaal in the Sanguine Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60244] = { id = 60244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trading Favors: Halls of Atonement", description = "The mechanisms by which each land of the Shadowlands operates are quite intriguing. Yet, I have always held a particular fascination with the venthyr of Revendreth.\n\nHow they siphon souls of their sins, storing them in strange stones, and dredge up minions from the muck that surrounds them -- it is all quite novel.\n\nThey keep their secrets close at hand, however, and will not willingly part with information. I offer trades for any of their tomes you might come into possession of.", progress = "Have you found something of interest?", completion = "A tome from Revendreth? Yes, let me see.\n\nIt chronicles the alchemical formulae necessary to form the dredger pools, and various recipes for forming and utilizing the little creatures. They are quite a curiosity, as much a minion as a reagent.\n\nI will gladly take this off of your hands in exchange for a trade. Here, choose.", objectives = "Obtain the Tome of Dredger Alchemy from Lord Chamberlain in the Halls of Atonement.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60245] = { id = 60245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trading Favors: De Other Side", description = "Mueh'zala is an ancient and primitive creature that commands a place known as De Other Side. Little is known about this land, as we are not permitted to visit. We have sent many offers of trade, yet there has never been a reply. \n\nA pity, as the few that have escaped Mueh'zala's clutches claim his domain to be a place of many oddities.\n\nWe would never ask you to venture into such danger. There is, however, a standing offer of trade for things procured from Mueh'zala's grasp.", progress = "You have the stench of death about you.", completion = "Oh, this is quite a find, is it not? Something from De Other Side. We so rarely get to glimpse such things, I shall study this with interest. It would appear to be from a forgotten, primitive race that worshipped Mueh'zala.\n\nA reward, of course, is in order. Make your choice.", objectives = "Obtain a Golden Death Mask from Mueh'zala in De Other Side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60246] = { id = 60246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trading Favors: Tirna Scithe", description = "The gorm devour anything in their path when left unchecked. We have sold more than a few of them as both pets and weapons. You do not want to see what a world looks like when they are introduced to it and allowed to infest.\n\nOr perhaps, mhm, you do? For some, that is entertainment.\n\nIt is difficult for us to explore Ardenweald with things as they are at this time. A fat, healthy gorm larva would fetch a fine price on the markets. I trust my meaning is understood?", progress = "Have you completed the task?", completion = "Oh, what is this? It is so bulbous and squirming, it must be close to the next molting. I am something of an amateur gorm-breeder myself, and will find a proper place to raise this one. \n\nYou may trust that I intend to destroy no worlds, I give you my word.\n\nNow, I must tend to him, gather something from our stocks on your way out.", objectives = "Obtain an Engorged Gorm Larva from Tred'ova in the Mists of Tirna Scithe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60247] = { id = 60247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trading Favors: Theater of Pain", description = "Grandmaster Vole runs the arena in Maldraxxus, where the champions of each of the houses compete for glory. Naturally, prizes are often awarded to the victors. \n\nThose of our kind do not often participate in such battles. To find such a prize for sale by one of us would be quite unusual indeed.\n\nI trust I need say no more? Let us keep this transaction between us, and I will be happy to part with some valuable goods.", progress = "Six, seven, eight... oh, yes? Do you have an offer of trade? I have much more inventory to catalogue.", completion = "Quite interesting, these coins are only granted to champions of the Maldraxxus arena after a certain amount of time in service. Purely ceremonial, they are worthless to most, but priceless to those that value ceremony. \n\nYou may take something with you in compensation.", objectives = "Obtain a Champion's Coin from Mordretha in the Theater of Pain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60248] = { id = 60248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trading Favors: Plaguefall", description = "Is is such a shame what happened to poor Margrave Stradama. Just between us, she was once one of our most favored trading partners. When things get lost in Maldraxxus they tend to end up at the bottom of her blighted pools.\n\nYou would not, perhaps, be interested in continuing this relationship on her behalf? We would, of course, compensate you quite well.\n\nI am sure she has little use for these possessions in her current state.", progress = "Oh, it is you again.", completion = "Oh my, this is quite a find. It is a catalogue of some of Stradama's procured objects, hidden away within her pools of plague. We will make good use of this, to be sure. \n\nChoose something to take with you, you have earned it.", objectives = "Obtain one of Stradama's Lost Ledgers from Margrave Stradama in Plaguefall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60249] = { id = 60249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trading Favors: Spires of Ascension", description = "The Kyrians of Bastion serve a unique role in the Shadowlands, ferrying mortal souls from their realms to ours. They are able to do so in great numbers, it would seem, in times of crisis or devastation.\n\nWe would like to know more about their travels to the realms beyond. \n\nSurely one of them has brought something back from another land? They are, after all, so very interested in memories.", progress = "How may I assist you?", completion = "A strange bauble, likely from another world. Yet, why would the paragon have brought this with her? \n\nPerhaps when carrying the soul of a child, as a reminder of something she had thought lost within herself? I will ponder this.\n\nYou may choose a reward from our stores.", objectives = "Obtain a Strange Doll from Devos, Paragon of Doubt in the Spires of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60250] = { id = 60250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valuable Find: Theater of Pain", description = "The Theater of Pain in Maldraxxus is a brutal place, where only the strongest survive. \n\nWith the houses so fiercely in competition with one another, it is considered a great point of pride to house a champion with a winning record.\n\nAs such, the house lords often outfit their contenders with powerful arms, armor, and trinkets. Often these are storied items that have been passed down through many battles.\n\nI would very much like to see such an item.", progress = "Were you victorious, or have you come to tend to your wounds?", completion = "The fools, giving away an object such as this as a mere trinket to be used in battle. Do they not know of its significance? Clearly not.\n\nLet me explain.\n\nThere is much we do not understand about the workings of this world. This city, Oribos, is made of a strange ore that we have not found anywhere else. Who made this place, and why?\n\nRelics of similar make like this are all that we have to tie together the threads of mystery.\n\nWe thank you for this gift. Please, take a treasure.", objectives = "Obtain the Ring of Otherworldly Metal from Mordretha in the Theater of Pain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60251] = { id = 60251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valuable Find: Plaguefall", description = "Life in Maldraxxus is one of constant warfare, the great houses in perpetual competition with one another. Every once in a great while, a house lord obtains an item or piece of knowledge of such rarity that it tips the scales in their favor.\n\nIt is possible, even probable, that this was the cause of the fate that befell the House of Plagues.\n\nI do not need to tell you how valuable such a rarity would be to us, do I?", progress = "Yes? I am quite busy here.", completion = "I can only decipher a few words of this missive, give me a moment.\n\nIt appears to be a warning from the Margrave to another lord of Maldraxxus, or perhaps another place.\n\nI see mention of the Primus, and discussion of his fate. Or someone else's? It is hard to tell. It appears to point to a location, but I cannot understand the description of the location.\n\nThis may be more valuable than you know for the fate of the Shadowlands. Choose a reward, I will continue my work on this.", objectives = "Obtain A Slimy Correspondence from Margrave Stradama in Plaguefall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60252] = { id = 60252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valuable Find: Spires of Ascension", description = "You have, no doubt, visited Bastion and seen what happens to souls that are accepted there. Their memories are extracted, viewed, and even stored in their great Temple of Wisdom.\n\nThis temple houses memories that may answer some of the greatest questions we have about our realm and the worlds beyond. It is a shame they are locked away.\n\nWe have heard that the fallen Paragon of Loyalty has interest in these memories. Any memory that would catch her attention would surely be worth trading for.", progress = "You have the look of one who has something to say.", completion = "This memory glass is old, very old. It may be the memory of a soul that moved on many years ago, we can never be certain. What is known is that the knowledge contained within can never be replicated, and soon, will never be seen again.\n\nI will immediately get to work in preserving what of it I can. I must ask that you take your leave now, please choose a suitably rich reward for your efforts.", objectives = "Obtain the Fading Memory Glass from Devos, Paragon of Doubt in the Spires of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60253] = { id = 60253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valuable Find: Necrotic Wake", description = "Once in a rare while, we find ourselves in possession of an object of exceptionally cryptic origin. These objects allow us a brief glimpse into the realms beyond our comprehension. \n\nIt may seem to you that I speak in riddles, yet so much of this realm is shrouded in mystery, even to us.\n\nThere are others that have sought to unravel the history of this realm. Should you happen upon one of their works, I will offer you a trade of exceptional value.", progress = "What have you found?", completion = "What sort of tome is this? May I leaf through it for a moment?\n\nWell then, this is quite a find. It represents many years cataloguing everything Nalthor knew about the origins of our world. The many curiosities of this place, from Zovaal's domain in the Maw, to the function of this strange city of Oribos.\n\nIt is surmised that they all tie together.\n\nI shall devour it with glee. Come, you may take one of our most prized possessions for it.", objectives = "Obtain \"The Origin of Death\" from Nalthor the Rimebinder in the Necrotic Wake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60254] = { id = 60254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valuable Find: Tirna Scithe", description = "The gorm are indiscriminate in what they consume, so long as it does not contain anima. A gorm queen that has lived for many generations may have any number of indestructible artifacts lodged within her belly. For this reason, sifting through a queen's carcass is not unlike treasure hunting for us.\n\nOne of the largest queens is currently consuming Tirna Scithe. She surely is bloated with valuables. Should you come upon anything particularly unusual, know that we will compensate you in kind.", progress = "You look as if you have been sifting through gorm carcass, or perhaps that is simply what you always look like?", completion = "We have found only a few objects similar to this in all of our time here, that I am aware of. Whether it belonged to a race of creature or automatons that came before us, or they still exist somewhere, we do not know.\n\nThe metallic fragments of this piece appear similar in design to the walls that surround us here in Oribos, yet we have never seen something like this moving around in the city.\n\nI will add it to the cache of relics related to these mysteries. Take a suitable reward with you.", objectives = "Obtain the Unusual Automaton Parts from Tred'ova in the Mists of Tirna Scithe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60255] = { id = 60255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valuable Find: De Other Side", description = "Mueh'zala has been around for many generations, how many exactly we cannot say. His domain is a land of mystery to us all. \n\nBut we are a people of probabilities and margins. A creature of that age, with such power, and the many ancient souls within his domain, has a great chance to be in possession of a relic of unfathomable rarity.\n\n<The light around Ta'lan's head flares brightly for a moment. He seems... excited?>\n\nSlay the foolish creature, bring me his secrets, I will reward you handsomely!", progress = "Have you brought something of interest?", completion = "This mask is similar in features to some of the automaton parts we have found in our time here in the Shadowlands. Perhaps it belonged to an ancient civilization? The information we have is scattered and incomplete.\n\nAny further pieces you may find of this sort will help us unravel these great mysteries. There seems to be a greater design to this place than we can see, yet so much of it eludes us.\n\nI will take it off of your hands, in exchange you make take one of our most valuable pieces.", objectives = "Obtain a Strange Ritual Mask from Mueh'zala in De Other Side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60256] = { id = 60256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valuable Find: Halls of Atonement", description = "The aristocracy of Revendreth trade in decadent and priceless shows of status with one another, but rarely with our kind.  Often they will travel with a piece or two affixed to their garb as a show of status.\n\nNow, many of their kind have sided with Sire Denathrius and against the denizens of the Shadowlands. They must, of course, be stopped. \n\nOf course.\n\nYet should you, in the process of doing so, relieve them of some of these possessions, know that I will trade generously.", progress = "How does the battle fare?", completion = "Now this is quite a find. A functional piece of the mysterious machinery that can be found around the Shadowlands.\n\nLook at how intricate the weaving of the golden orb is, how the energy seems to be contained from somewhere within, yet in a construct that is almost beyond imagining. What could have made such an object? Where are they now?\n\nWe shall begin to investigate with fervor. Do drop in if you find anything similar, and take a reward before you go.", objectives = "Obtain the Golden Orb of Energy from Lord Chamberlain in the Halls of Atonement.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60257] = { id = 60257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valuable Find: Sanguine Depths", description = "General Kaal has slain many foes, and in a bag at her side, she holds the skulls of those she considers her most precious kills. Not all of them, of course, have skulls --  it is a bag of eclectic contents.\n\nContained within, we have heard, is the head of one of our kind. We do not know to whom it might belong, for we do not often find ourselves running afoul of the venthyr.\n\nSuch a strange mystery must be solved. I will, of course, provide great compensation.", progress = "What information do you bring?", completion = "This... is not what I expected.\n\nIt is similar in appearance to our people, yet so very different. Are there others of our kind out there? Who are they, and where do they reside? Why have they not made contact with us? Or are they hiding themselves purposefully?\n\nIs this a history we knew but have forgotten? I have so many questions.\n\nI thank you for this, it is quite meaningful to us. Please, take a relic of power from the treasury.", objectives = "Obtain an Ancient Broker Headpiece from General Kaal in the Sanguine Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60264] = { id = 60264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul Survivor", description = "I knew when you helped me in the Etheric Vault, that you were a just and worthy leader.\n\nI have come here to offer you my help and services in your efforts to bring Maldraxxus back into balance.\n\nPlease, build a construct for me, and allow me to help you as you have helped me.", progress = "Are you willing to do this?", completion = "Miru is a very old soul and a survivor. We would be well aided by building him a construct.", objectives = "Take specifications for Miru's construct.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60265] = { id = 60265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupting the Chain", description = "From the desk of the Tithelord:\n\nAll supply carriages must re-route to Stonevigil for collection assistance. Once complete, you may resume your regularly scheduled routes.", completion = "Well done.\n\nWe will bleed this miscreant \"Harvester\" dry.", objectives = "Destroy the Darkhaven and Manor carriages in Stonevigil Overlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60267] = { id = 60267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prison of the Forgotten", description = "<As you stare at the object you've found, you sense it may lead you to another part of this wretched tower.\n\nPerhaps Ve'nari may know more of its purpose.>", progress = "<The lock appears to be sturdy, yet old and untouched. Dust has collected considerably upon it.>", completion = "<As you place the key into the device, it shudders for a moment and begins to unlock.>", objectives = "Take the object back to Ve'nari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60268] = { id = 60268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Within", description = "Who... who are you? Have you come to extract more of my memories?\n\nI'm afraid there aren't any useful ones left, save for the memories of my imprisonment.\n\nOr perhaps you're here for something else?", progress = "What do you want of me?", completion = "You could be the key to my freedom. Will you help me, mortal?", objectives = "Speak with the prisoner and learn of his situation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60269] = { id = 60269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reawakening", description = "If you can retrieve my memories, I can help you. At least I believe I can.\n\nThen, perhaps, we can help each other.", progress = "Have you found what was taken from me?", completion = "It's been an age since I knew anything other than the contours of this hellish prison.\n\nThank you, mortal. Now to aid you.", objectives = "Find a stolen memory of the Runecarver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60270] = { id = 60270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Damned Pact", description = "Yes... I begin to remember. Power. Power with a purpose. That is what I can offer.\n\nRunes. Runes are the key. I've recalled some of them, but to infuse them into your equipment, I require my hands.\n\nWell, one hand would suffice. Both would be better.\n\nFind a way to free me from my bonds, mortal. Then I can offer the power you seek. After that, freedom... and perhaps the downfall of the one who bound me.", completion = "Breaking a prisoner's chains? I'm not sure I know how that could be done, unless...\n\nIt's dangerous, but I believe there may be a way.", objectives = "Discover a way to break the Runecarver free from his chains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60271] = { id = 60271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grave Chance", description = "First you'll need a vessel to house anima and a way to expel it. I happen to possess such a device, which I'll be pleased to give to you.\n\nFor a price, of course.\n\nYou recall Zovaal's Cauldron, I trust? The denizens there were forged in unholy fire. Assuming their anima is of a similar nature, it should be able to melt even the metals of the tower.\n\nWith my device and their anima, I believe you can achieve your goal, Maw Walker.", progress = "Were you able to acquire the anima?", completion = "Your success continues to impress, Maw Walker.\n\nThough I admit, such feats are becoming less unexpected as I come to know you more.", objectives = "Purchase an Anima Supricifer from Ve'nari and recover 5 Molten Anima.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60272] = { id = 60272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weak Link", description = "This ought to be enough to break the bonds that hold your newfound ally.\n\n<Ve'nari pauses for a moment.>\n\nBefore you do so, I offer a word of warning.\n\nNo creature imprisoned in that place should be trusted. Tread carefully, mortal. \n\nAfter all, it would be a shame to lose so valuable a business partner.", progress = "It's good to remember something new again.", completion = "Freedom. Of a sort. Yes... this is good. You have my thanks.\n\nWhat was it you wanted? Ah, power. Yes. Very well, then.", objectives = "Break the Runecarver free.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
